-- Reglas tributarias de Perú en borrador, con fuente oficial de la SUNAT. Ninguna está verificada: requieren revisión de un contador.
insert into public.ai_knowledge (kind, area, country_code, topic, title, summary, source_name, source_url, license, lang, status) values
('tax_rule','impuestos','PE','igv','IGV en Perú: tasa y composición con el IPM (2026)',
$k$La tasa total del Impuesto General a las Ventas (IGV) en Perú es de 18 % sobre la operación gravada. Esa tasa incluye el Impuesto de Promoción Municipal (IPM). Según la guía de SUNAT, la Ley 32387 incrementa el IPM de forma gradual hasta 4 %, de modo que la tasa total no cambia pero su composición sí: en 2026 es 15,5 % de IGV más 2,5 % de IPM; en 2027, 15,0 % más 3,0 %; en 2028, 14,5 % más 3,5 %; y en 2029, 14,0 % más 4,0 %. Muchas páginas secundarias todavía mencionan 16 % más 2 %, que corresponde a la composición anterior. El IGV por pagar se calcula restando el IGV de las compras al IGV de las ventas, y se declara y paga cada mes según el último dígito del RUC.$k$,
'SUNAT, Orientación tributaria (IGV: concepto, tasa y operaciones gravadas)','https://orientacion.sunat.gob.pe/3053-concepto-tasa-y-operaciones-gravadas-igv-empresas',
'Material informativo de la SUNAT del Perú; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','impuestos','PE','regimenes','Regímenes tributarios de Perú: visión general',
$k$La SUNAT establece cuatro regímenes tributarios para quien inicia o tiene un negocio: Nuevo Régimen Único Simplificado (NRUS), Régimen Especial del Impuesto a la Renta (RER), Régimen MYPE Tributario (RMT) y Régimen General (RG). El NRUS es solo para personas naturales; el RER, el RMT y el RG admiten personas naturales y jurídicas. Los límites de ingresos son: NRUS hasta S/ 96 000 al año o S/ 8 000 al mes; RER hasta S/ 525 000 al año; RMT hasta 1 700 UIT de ingresos netos en el año; RG sin límite. Hay actividades que no pueden acogerse al NRUS ni al RER. La elección depende del tipo de actividad, los ingresos proyectados y los clientes, por lo que conviene que la confirme un contador.$k$,
'SUNAT, Emprender: regímenes tributarios','https://emprender.sunat.gob.pe/ruc/regimenes-tributarios-mype/regimenes-tributarios',
'Material informativo de la SUNAT del Perú; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','impuestos','PE','nrus','Nuevo RUS (NRUS) en Perú: límites y cuotas',
$k$El Nuevo RUS es un régimen simplificado para personas naturales con negocios pequeños. Tiene dos categorías con cuota fija mensual: la categoría 1, con ingresos o compras mensuales de hasta S/ 5 000, paga S/ 20; la categoría 2, con ingresos o compras mensuales de hasta S/ 8 000, paga S/ 50. El límite anual de ingresos y de compras es de S/ 96 000. El pago es mensual y cancelatorio, sin declaración anual. Quienes están en este régimen emiten boletas de venta, no facturas. Dato a confirmar con un contador antes de usarlo como regla verificada: si el negocio supera el límite, debe pasar a otro régimen.$k$,
'SUNAT, Emprender: regímenes tributarios (NRUS)','https://emprender.sunat.gob.pe/ruc/regimenes-tributarios-mype/regimenes-tributarios',
'Material informativo de la SUNAT del Perú; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','impuestos','PE','rer','Régimen Especial de Renta (RER) en Perú',
$k$El RER está dirigido a personas naturales y jurídicas con ingresos anuales de hasta S/ 525 000 y compras anuales de hasta S/ 525 000. La SUNAT lo sugiere para quien tiene clientes empresas, necesita emitir facturas y puede llevar una contabilidad simple. El pago mensual del impuesto a la renta se reporta en fuentes de apoyo como 1,5 % de los ingresos netos del mes, y el IGV sigue siendo 18 % en total; esa cifra de 1,5 % no se tomó de la ficha oficial del RER y debe confirmarla un contador antes de verificarse. Hay actividades que no pueden acogerse a este régimen.$k$,
'SUNAT, Emprender: regímenes tributarios (RER)','https://emprender.sunat.gob.pe/ruc/regimenes-tributarios-mype/regimenes-tributarios',
'Material informativo de la SUNAT del Perú; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','impuestos','PE','rmt','Régimen MYPE Tributario (RMT) en Perú',
$k$El RMT está dirigido a micro y pequeñas empresas, personas naturales o jurídicas, con rentas de tercera categoría e ingresos netos que no superen 1 700 UIT en el año. Si superan ese tope pasan al Régimen General. El impuesto a la renta anual se calcula sobre la utilidad: 10 % hasta 15 UIT (S/ 82 500 con la UIT vigente que indica gob.pe) y 29,5 % sobre el exceso. Durante el año se hacen pagos a cuenta mensuales; el material de SUNAT indica 1 % de los ingresos netos hasta 300 UIT, y para más de 300 UIT hasta 1 700 UIT, el coeficiente o 1,5 %. Con ingresos de hasta 300 UIT, los libros son el Registro de Ventas, el Registro de Compras y el Libro Diario de formato simplificado. Presenta declaración anual.$k$,
'gob.pe, Régimen MYPE Tributario (RMT) y SUNAT Emprender','https://www.gob.pe/6990-regimen-mype-tributario-rmt',
'Material informativo del Estado peruano (gob.pe/SUNAT); no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','impuestos','PE','regimen_general','Régimen General del Impuesto a la Renta en Perú',
$k$El Régimen General no tiene límite de ingresos ni de compras y admite personas naturales y jurídicas. El impuesto a la renta anual es de 29,5 % sobre la renta neta, con pagos a cuenta mensuales, y exige contabilidad completa según el nivel de ingresos. Un negocio del RMT que supera 1 700 UIT de ingresos netos en el año debe ingresar a este régimen. La SUNAT recomienda evaluarlo cuando el negocio crece. Cualquier cambio de régimen y sus plazos debe confirmarse con un contador y en la SUNAT.$k$,
'SUNAT, Emprender: regímenes tributarios (RG)','https://emprender.sunat.gob.pe/ruc/regimenes-tributarios-mype/regimenes-tributarios',
'Material informativo de la SUNAT del Perú; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','contabilidad','PE','comprobantes_electronicos','Comprobantes de pago electrónicos en Perú',
$k$Según una nota de la SUNAT de mayo de 2026, la Resolución de Superintendencia 000075-2026/SUNAT establece que los contribuyentes recién inscritos en el RUC que opten por el Régimen MYPE Tributario, el RER o el Régimen General quedan designados como emisores electrónicos desde el día de su inscripción. Esto aplica al Sistema de Emisión Electrónica (SEE): facturas, boletas, notas de crédito y de débito. Las personas del NRUS emiten boletas de venta. Para confirmar si una empresa ya existente es emisora electrónica y por qué sistema debe emitir, se consulta a la SUNAT o a un contador.$k$,
'SUNAT (gob.pe), Emisores electrónicos desde la inscripción en el RUC','https://www.gob.pe/institucion/sunat/noticias/1398485-contribuyentes-seran-designados-como-emisores-electronicos-desde-que-se-inscriban-en-el-ruc',
'Material informativo de la SUNAT del Perú; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','legal','PE','declaracion_pagos','Declaración y pago mensual en Perú: cronograma por último dígito del RUC',
$k$Las declaraciones y pagos del IGV y de los pagos a cuenta del impuesto a la renta son mensuales y se presentan según el cronograma de SUNAT, que depende del último dígito del RUC (los dígitos 0 a 9 tienen fechas distintas cada mes). Se realizan por SUNAT Operaciones en Línea con Clave SOL, por ejemplo con el Formulario Virtual 621 (IGV-Renta mensual). Las fechas exactas cambian cada año, por lo que deben leerse en el cronograma oficial vigente antes de indicarlas a un usuario. El sistema de detracciones, percepciones y retenciones del IGV tiene reglas propias que debe revisar un contador.$k$,
'SUNAT, Emprender: IGV y cronograma','https://emprender.sunat.gob.pe/principales-impuestos/impuesto-general-las-ventas-igv/impuesto-general-las-ventas',
'Material informativo de la SUNAT del Perú; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft');
